"use client";

import { useMemo, useState, type ReactNode } from "react";
import {
  DataGridBody,
  DataGridHeader,
  DataGridProvider,
  DataGridRoot,
  defineColumns,
  useDataGridSelectedRows,
} from "@/registry/default/components/data-grid/data-grid";
import { DataGridStatusBar } from "@/registry/default/components/data-grid-status-bar/data-grid-status-bar";
import { DataGridPaginationBar, useDataGridServerPager } from "@/registry/default/components/data-grid-pagination/data-grid-pagination";
import { generateSales, type SaleRow } from "./sales-data";

const TOTAL = 237;
const PAGE_SIZE = 10;
const SALES = generateSales(TOTAL);

const columns = defineColumns<SaleRow>()([
  { id: "id", header: "ID", accessorKey: "id", type: "text", width: 90 },
  { id: "customer", header: "Customer", accessorKey: "customer", type: "text", width: 140, flex: 1 },
  { id: "make", header: "Make", accessorKey: "make", type: "text", width: 100, flex: 1 },
  { id: "model", header: "Model", accessorKey: "model", type: "text", width: 100, flex: 1 },
  { id: "price", header: "Price", accessorKey: "price", type: "number", width: 100 },
] as const);

function SelectionPanel(): ReactNode {
  const selected = useDataGridSelectedRows();
  const summary = selected.mode === "ids" ? `${selected.count} checked` : `all matching, ${selected.count?.toLocaleString("en-US") ?? "an unknown number of"} rows`;
  const list = selected.mode === "ids" ? selected.ids : selected.excludedIds;
  return (
    <div className="flex flex-col gap-2 rounded-md border border-border p-2 text-sm">
      <strong>{summary}</strong>
      <code className="block truncate text-xs text-muted-foreground">
        {selected.mode === "ids" ? "ids" : "excludedIds"}: [{list.slice(0, 6).join(", ")}
        {list.length > 6 ? `, +${list.length - 6} more` : ""}]
      </code>
    </div>
  );
}

/** A paged "server": checks survive page changes, and "select all matching" covers rows that were never loaded. */
export default function DataGridServerSelectionDemo(): ReactNode {
  const [page, setPage] = useState(1);
  const rows = useMemo(() => SALES.slice((page - 1) * PAGE_SIZE, page * PAGE_SIZE), [page]);
  const { pager } = useDataGridServerPager({ page, pageSize: PAGE_SIZE, totalRowCount: TOTAL, onPageChange: setPage, pageSizeOptions: [PAGE_SIZE] });

  return (
    <div className="flex w-full flex-col gap-2">
      <p className="m-0 text-sm text-muted-foreground">
        Check rows on page 1, go to page 3, and check more. Then check the header checkbox: the bar under the grid offers "Select all {TOTAL} matching". Uncheck a row and change pages.
      </p>
      <DataGridProvider data={rows} columns={columns} readOnly rowMarkers="checkbox" checkedRowsLifetime="across-filters" totalRowCount={TOTAL}>
        <DataGridRoot className="h-[360px]">
          <DataGridHeader />
          <DataGridBody />
        </DataGridRoot>
        <DataGridPaginationBar {...pager} />
        <DataGridStatusBar />
        <SelectionPanel />
      </DataGridProvider>
    </div>
  );
}

/** One car sold by a dealership. */
export type SaleRow = {
  id: string;
  soldOn: string;
  region: string;
  dealership: string;
  salesperson: string;
  make: string;
  model: string;
  customer: string;
  price: number;
  discount: number;
  financed: boolean;
};

export const REGIONS = ["North", "South", "East", "West"];
export const DEALERSHIPS = ["Northgate Motors", "Pine Ridge Cars", "Bayview Autos", "Southfield Motors", "Eastbrook Cars", "Harbor Point Motors", "Westlake Autos", "Canyon Road Motors"];
export const MAKES = ["Kestrel", "Marlow", "Nordvik", "Solenne", "Vantor"];
const SALESPEOPLE = ["Dana Brooks", "Eli Moreno", "Fern Walsh", "Gus Ortega", "Hana Ito", "Ivan Petrov", "Jade Lin", "Kofi Mensah", "Lena Fischer", "Milo Grant", "Nia Duarte", "Omar Aziz", "Pia Lund", "Raul Vega", "Sana Mir", "Theo Clark"];
const MODELS = [["Brook", "Glide", "Summit"], ["Coast", "Harbor", "Tide"], ["Birch", "Fjord", "Frost"], ["Dawn", "Lumen", "Opal"], ["Ember", "Flint", "Quarry"]];
// Unequal shares per region and a different make mix in each region, so group totals differ.
const REGION_SLOTS = [0, 0, 0, 0, 1, 1, 1, 2, 2, 3];
const MAKE_MIX = [
  [0, 0, 0, 1, 2, 3, 4, 1],
  [1, 1, 1, 2, 0, 3, 4, 2],
  [2, 2, 3, 3, 3, 0, 1, 4],
  [4, 4, 4, 3, 0, 1, 2, 4],
];
const FIRST = ["Alex", "Sam", "Jordan", "Taylor", "Morgan", "Casey", "Riley", "Jamie", "Avery", "Quinn", "Drew", "Robin"];
const LAST = ["Smith", "Garcia", "Chen", "Patel", "Novak", "Okafor", "Larsen", "Rossi", "Kim", "Silva", "Meyer", "Haddad"];

/** `count` fictional car sales. Index arithmetic instead of `Math.random` keeps the server and client markup equal. */
export const generateSales = (count: number): SaleRow[] =>
  Array.from({ length: count }, (_, index) => {
    const region = REGION_SLOTS[index % REGION_SLOTS.length]!;
    const mix = MAKE_MIX[region]!;
    const make = mix[Math.floor(index / REGION_SLOTS.length) % mix.length]!;
    const model = Math.floor(index / 80) % 3;
    const dealership = region * 2 + (Math.floor(index / 7) % 3 === 0 ? 1 : 0);
    return {
      id: `sale-${index + 1}`,
      soldOn: new Date(Date.UTC(2025, 0, 1 + ((index * 7) % 365))).toISOString().slice(0, 10),
      region: REGIONS[region]!,
      dealership: DEALERSHIPS[dealership]!,
      salesperson: SALESPEOPLE[dealership * 2 + (Math.floor(index / 13) % 2)]!,
      make: MAKES[make]!,
      model: MODELS[make]![model]!,
      customer: `${FIRST[Math.floor(index / 5) % FIRST.length]!} ${LAST[(index * 7) % LAST.length]!}`,
      price: 21000 + make * 6000 + model * 9000 + ((index * 37) % 41) * 100,
      discount: ((index * 7) % 13) * 250,
      financed: index % 3 !== 0,
    };
  });
